The client advertises `workspace.diagnostics.refreshSupport: true` but the `workspace/diagnostic/refresh` handler currently just returns `null` and doesn't trigger any re-pull. Per the LSP diagnostics spec, receiving this request should cause the client to re-request diagnostics (at least for currently-open documents), otherwise servers that rely on refresh will never update pull diagnostics.
```suggestion
  const applyPulledDiagnostics = (
    filePath: string,
    report:
      | {
          kind?: "full" | "unchanged"
          items?: VSCodeDiagnostic[]
          relatedDocuments?: Record<
            string,
            {
              kind?: "full" | "unchanged"
              items?: VSCodeDiagnostic[]
            }
          >
        }
      | null
      | undefined,
  ) => {
    if (!report) return

    const previous = published.get(filePath)
    published.set(filePath, {
      at: Date.now(),
      version: previous?.version,
    })

    if (report.kind !== "unchanged" && Array.isArray(report.items)) {
      updatePushDiagnostics(filePath, report.items)
    }

    for (const [uri, relatedReport] of Object.entries(report.relatedDocuments ?? {})) {
      const relatedPath = getFilePath(uri)
      if (!relatedPath) continue

      const relatedPrevious = published.get(relatedPath)
      published.set(relatedPath, {
        at: Date.now(),
        version: relatedPrevious?.version,
      })

      if (relatedReport.kind !== "unchanged" && Array.isArray(relatedReport.items)) {
        updatePushDiagnostics(relatedPath, relatedReport.items)
      }
    }
  }
  connection.onRequest("workspace/workspaceFolders", async () => [
    {
      name: "workspace",
      uri: pathToFileURL(input.root).href,
    },
  ])
  connection.onRequest("workspace/diagnostic/refresh", async () => {
    l.info("workspace/diagnostic/refresh")

    const trackedFilePaths = new Set([...published.keys(), ...pushDiagnostics.keys()])
    await Promise.allSettled(
      [...trackedFilePaths].map(async (filePath) => {
        try {
          const report = await connection.sendRequest<{
            kind?: "full" | "unchanged"
            items?: VSCodeDiagnostic[]
            relatedDocuments?: Record<
              string,
              {
                kind?: "full" | "unchanged"
                items?: VSCodeDiagnostic[]
              }
            >
          }>("textDocument/diagnostic", {
            textDocument: {
              uri: pathToFileURL(filePath).href,
            },
          })
          applyPulledDiagnostics(filePath, report)
        } catch (error) {
          l.warn("workspace/diagnostic/refresh failed", {
            path: filePath,
            error,
          })
        }
      }),
    )

    return null
  })
```

In the local `app/dist` serving path, a request like `/.` will resolve `resolvedPath` to `distDir` (passing the current traversal guard) and then attempt `fs.readFile(distDir)`, which will throw `EISDIR` and likely surface as a 500. Consider normalizing dot-segments (`reqPath`), or after resolving, `stat()` the path and only `readFile` when it’s a file; if it’s a directory, fall back to `index.html` (or 404).
```suggestion
      const normalizedReqPath = reqPath === "/" ? "/index.html" : path.posix.normalize(reqPath)
      const relativeReqPath = normalizedReqPath.replace(/^\/+/, "")
      const filePath = path.join(distDir, ...relativeReqPath.split("/"))
      const resolvedPath = path.resolve(filePath)
      if (!resolvedPath.startsWith(distDir + path.sep) && resolvedPath !== distDir) {
        return c.json({ error: "Forbidden" }, 403)
      }

      let servePath: string | null = null
      try {
        const stats = await fs.stat(resolvedPath)
        if (stats.isFile()) {
          servePath = resolvedPath
        } else if (stats.isDirectory()) {
          const directoryIndexPath = path.join(resolvedPath, "index.html")
          const resolvedDirectoryIndexPath = path.resolve(directoryIndexPath)
          if (
            (!resolvedDirectoryIndexPath.startsWith(distDir + path.sep) && resolvedDirectoryIndexPath !== distDir)
          ) {
            return c.json({ error: "Forbidden" }, 403)
          }
          try {
            const directoryIndexStats = await fs.stat(resolvedDirectoryIndexPath)
            if (directoryIndexStats.isFile()) {
              servePath = resolvedDirectoryIndexPath
            }
          } catch {
            // Fall through to SPA fallback below when the directory index is missing.
          }
        }
      } catch {
        // Fall through to SPA fallback below when the requested path does not exist.
      }

      if (servePath) {
        const content = await fs.readFile(servePath)
        const mime = getMimeType(servePath) ?? "text/plain"
        c.header("Content-Type", mime)
        if (mime.startsWith("text/html")) {
          c.header("Content-Security-Policy", csp(extractScriptHashes(new TextDecoder().decode(content)), true))
        }
        return c.body(new Uint8Array(content))
      }

      // SPA fallback: serve index.html for unknown routes
      const indexPath = path.join(distDir, "index.html")
      const resolvedIndexPath = path.resolve(indexPath)
      if (!resolvedIndexPath.startsWith(distDir + path.sep) && resolvedIndexPath !== distDir) {
        return c.json({ error: "Forbidden" }, 403)
      }
      try {
        const indexStats = await fs.stat(resolvedIndexPath)
        if (indexStats.isFile()) {
          const content = await fs.readFile(resolvedIndexPath)
          c.header("Content-Type", "text/html")
          c.header("Content-Security-Policy", csp(extractScriptHashes(new TextDecoder().decode(content)), true))
          return c.body(new Uint8Array(content))
        }
      } catch {
        // No local SPA fallback available; continue to proxied UI below.
